BEGIN CASE p_type
WHEN 'DoclingDocument' THEN RETURN NOT EXISTS(SELECT FROM jsonb_object_keys(p_scalars||p_fields) k WHERE NOT k=ANY(ARRAY['schema_name','version','name','origin','furniture','body','groups','texts','pictures','tables','key_value_items','form_items','field_regions','field_items','pages']::text[])) AND (p_scalars ? 'name' OR p_fields ? 'name') AND (NOT p_scalars ? 'schema_name' OR ((jsonb_typeof(p_scalars->'schema_name')='string' AND p_scalars->'schema_name'='"DoclingDocument"'::jsonb))) AND (NOT p_scalars ? 'version' OR ((jsonb_typeof(p_scalars->'version')='string'))) AND (NOT p_scalars ? 'name' OR ((jsonb_typeof(p_scalars->'name')='string'))) AND (NOT p_scalars ? 'origin' OR ((jsonb_typeof(p_scalars->'origin')='null'))) AND (NOT p_scalars ? 'furniture' OR (false)) AND (NOT p_scalars ? 'body' OR (false)) AND (NOT p_scalars ? 'groups' OR (false)) AND (NOT p_scalars ? 'texts' OR (false)) AND (NOT p_scalars ? 'pictures' OR (false)) AND (NOT p_scalars ? 'tables' OR (false)) AND (NOT p_scalars ? 'key_value_items' OR (false)) AND (NOT p_scalars ? 'form_items' OR (false)) AND (NOT p_scalars ? 'field_regions' OR (false)) AND (NOT p_scalars ? 'field_items' OR (false)) AND (NOT p_scalars ? 'pages' OR (false));
WHEN 'BaseMeta' THEN RETURN NOT EXISTS(SELECT FROM jsonb_object_keys(p_scalars||p_fields) k WHERE NOT k=ANY(ARRAY['summary','language','entities','keywords','topics']::text[])) AND (NOT p_scalars ? 'summary' OR ((jsonb_typeof(p_scalars->'summary')='null'))) AND (NOT p_scalars ? 'language' OR ((jsonb_typeof(p_scalars->'language')='null'))) AND (NOT p_scalars ? 'entities' OR ((jsonb_typeof(p_scalars->'entities')='null'))) AND (NOT p_scalars ? 'keywords' OR ((jsonb_typeof(p_scalars->'keywords')='null'))) AND (NOT p_scalars ? 'topics' OR ((jsonb_typeof(p_scalars->'topics')='null')));
WHEN 'BoundingBox' THEN RETURN NOT EXISTS(SELECT FROM jsonb_object_keys(p_scalars||p_fields) k WHERE NOT k=ANY(ARRAY['l','t','r','b','coord_origin']::text[])) AND (p_scalars ? 'l' OR p_fields ? 'l') AND (p_scalars ? 't' OR p_fields ? 't') AND (p_scalars ? 'r' OR p_fields ? 'r') AND (p_scalars ? 'b' OR p_fields ? 'b') AND (NOT p_scalars ? 'l' OR (((jsonb_typeof(p_scalars->'l')='number' OR (jsonb_typeof(p_scalars->'l')='object' AND p_scalars->'l' ? 'native_float64' AND (p_scalars->'l'->>'native_float64') ~ '^[0-9a-f]{16}$'))))) AND (NOT p_scalars ? 't' OR (((jsonb_typeof(p_scalars->'t')='number' OR (jsonb_typeof(p_scalars->'t')='object' AND p_scalars->'t' ? 'native_float64' AND (p_scalars->'t'->>'native_float64') ~ '^[0-9a-f]{16}$'))))) AND (NOT p_scalars ? 'r' OR (((jsonb_typeof(p_scalars->'r')='number' OR (jsonb_typeof(p_scalars->'r')='object' AND p_scalars->'r' ? 'native_float64' AND (p_scalars->'r'->>'native_float64') ~ '^[0-9a-f]{16}$'))))) AND (NOT p_scalars ? 'b' OR (((jsonb_typeof(p_scalars->'b')='number' OR (jsonb_typeof(p_scalars->'b')='object' AND p_scalars->'b' ? 'native_float64' AND (p_scalars->'b'->>'native_float64') ~ '^[0-9a-f]{16}$'))))) AND (NOT p_scalars ? 'coord_origin' OR ((jsonb_typeof(p_scalars->'coord_origin')='string' AND p_scalars->'coord_origin' IN ('"TOPLEFT"'::jsonb,'"BOTTOMLEFT"'::jsonb))));
WHEN 'ChartBar' THEN RETURN NOT EXISTS(SELECT FROM jsonb_object_keys(p_scalars||p_fields) k WHERE NOT k=ANY(ARRAY['label','values']::text[])) AND (p_scalars ? 'label' OR p_fields ? 'label') AND (p_scalars ? 'values' OR p_fields ? 'values') AND (NOT p_scalars ? 'label' OR ((jsonb_typeof(p_scalars->'label')='string'))) AND (NOT p_scalars ? 'values' OR (((jsonb_typeof(p_scalars->'values')='number' OR (jsonb_typeof(p_scalars->'values')='object' AND p_scalars->'values' ? 'native_float64' AND (p_scalars->'values'->>'native_float64') ~ '^[0-9a-f]{16}$')))));
WHEN 'ChartLine' THEN RETURN NOT EXISTS(SELECT FROM jsonb_object_keys(p_scalars||p_fields) k WHERE NOT k=ANY(ARRAY['label','values']::text[])) AND (p_scalars ? 'label' OR p_fields ? 'label') AND (p_scalars ? 'values' OR p_fields ? 'values') AND (NOT p_scalars ? 'label' OR ((jsonb_typeof(p_scalars->'label')='string'))) AND (NOT p_scalars ? 'values' OR (false));
WHEN 'ChartPoint' THEN RETURN NOT EXISTS(SELECT FROM jsonb_object_keys(p_scalars||p_fields) k WHERE NOT k=ANY(ARRAY['value']::text[])) AND (p_scalars ? 'value' OR p_fields ? 'value') AND (NOT p_scalars ? 'value' OR (false));
