DECLARE job ops.task; run ops.run; product jsonb:='{}'; digest text:=encode(sha256(p_payload),'hex');
 wire json; field_name text; field_value json; envelope_fields text[]:=ARRAY[]::text[];
 input_rows json; occurrence_rows json; relation_rows json; coverage_rows json; mapping_rows json;
 previous ops.pdf_product; input jsonb; occurrence jsonb; relation jsonb; endpoint jsonb; coverage jsonb; mapping_report jsonb; pin ops.pdf_product; idx bigint; eid bigint; original text;
BEGIN
 SELECT r.* INTO STRICT run FROM ops.run r JOIN ops.task t ON t.run_id=r.id WHERE t.id=p_task FOR SHARE OF r;
 SELECT * INTO STRICT job FROM ops.task WHERE id=p_task AND run_id=run.id FOR UPDATE;
 IF job.attempt<>p_attempt OR job.claimed_by IS DISTINCT FROM p_holder THEN RAISE EXCEPTION 'stale recognition observation attempt' USING ERRCODE='P0004'; END IF;
 wire:=convert_from(p_payload,'UTF8')::json;
 IF json_typeof(wire) IS DISTINCT FROM 'object' OR wire->>'kind' IS DISTINCT FROM 'recognition_observation' THEN RAISE EXCEPTION 'parsing record must be an object: PdfIntegratedProduct' USING ERRCODE='23514'; END IF;
 FOR field_name,field_value IN SELECT key,value FROM json_each(wire) LOOP
  envelope_fields:=array_append(envelope_fields,field_name);
  CASE field_name
   WHEN 'inputs' THEN input_rows:=field_value;
   WHEN 'occurrences' THEN occurrence_rows:=field_value;
   WHEN 'relations' THEN relation_rows:=field_value;
   WHEN 'coverage' THEN coverage_rows:=field_value;
   WHEN 'mapping_reports' THEN mapping_rows:=field_value;
   WHEN 'content' THEN RAISE EXCEPTION 'document content is not an observation' USING ERRCODE='23514';
   ELSE product:=product||jsonb_build_object(field_name,field_value::jsonb);
  END CASE;
 END LOOP;
 IF jsonb_typeof(product) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfObservationProduct' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM unnest(envelope_fields) key WHERE key<>ALL(ARRAY['mapping_reports','version','kind','product_key','artifact_digest','recipe_digest','inputs','occurrences','relations','coverage','health','observation','content'])) OR ('mapping_reports'=ANY(envelope_fields) AND (json_typeof(mapping_rows) IS DISTINCT FROM 'array')) OR NOT ('version'=ANY(envelope_fields)) OR ('version'=ANY(envelope_fields) AND (jsonb_typeof(product->'version') IS DISTINCT FROM 'number' OR product->>'version' !~ '^[0-9]+$')) OR ('version'=ANY(envelope_fields) AND (product->>'version')::numeric < 1) OR ('version'=ANY(envelope_fields) AND (product->>'version')::numeric > 1) OR NOT ('kind'=ANY(envelope_fields)) OR ('kind'=ANY(envelope_fields) AND (jsonb_typeof(product->'kind') IS DISTINCT FROM 'string' OR product->>'kind' NOT IN ('recognition_observation'))) OR NOT ('product_key'=ANY(envelope_fields)) OR ('product_key'=ANY(envelope_fields) AND (jsonb_typeof(product->'product_key') IS DISTINCT FROM 'string')) OR NOT ('artifact_digest'=ANY(envelope_fields)) OR ('artifact_digest'=ANY(envelope_fields) AND (jsonb_typeof(product->'artifact_digest') IS DISTINCT FROM 'string')) OR ('artifact_digest'=ANY(envelope_fields) AND product->>'artifact_digest' !~ '^[0-9a-f]{64}$') OR NOT ('recipe_digest'=ANY(envelope_fields)) OR ('recipe_digest'=ANY(envelope_fields) AND (jsonb_typeof(product->'recipe_digest') IS DISTINCT FROM 'string')) OR ('recipe_digest'=ANY(envelope_fields) AND product->>'recipe_digest' !~ '^[0-9a-f]{64}$') OR ('inputs'=ANY(envelope_fields) AND (json_typeof(input_rows) IS DISTINCT FROM 'array')) OR ('occurrences'=ANY(envelope_fields) AND (json_typeof(occurrence_rows) IS DISTINCT FROM 'array')) OR ('relations'=ANY(envelope_fields) AND (json_typeof(relation_rows) IS DISTINCT FROM 'array')) OR NOT ('coverage'=ANY(envelope_fields)) OR ('coverage'=ANY(envelope_fields) AND (json_typeof(coverage_rows) IS DISTINCT FROM 'array' OR json_array_length(coverage_rows) < 1)) OR NOT ('health'=ANY(